// Which icon a detected name gets. First match wins, so the more specific names come first.
const RULES = [
  [/woocommerce|^woo\b/i, 'woo'], [/^wordpress/i, 'wordpress'], [/shopify/i, 'shopify'], [/^wix/i, 'wix'], [/squarespace/i, 'squarespace'], [/webflow/i, 'webflow'],
  [/framer/i, 'framer'], [/joomla/i, 'joomla'], [/drupal/i, 'drupal'], [/prestashop/i, 'prestashop'], [/^ghost/i, 'ghost'], [/blogger/i, 'blogger'], [/hubspot/i, 'hubspot'],
  [/^elementor( pro)?$/i, 'elementor'], [/^bricks/i, 'bricks'], [/^oxygen/i, 'oxygen'],
  [/cloudflare/i, 'cloudflare'], [/vercel/i, 'vercel'], [/netlify/i, 'netlify'], [/github/i, 'github'], [/^php/i, 'php'], [/nginx|openresty/i, 'nginx'], [/apache/i, 'apache'],
  [/godaddy/i, 'godaddy'], [/namecheap/i, 'namecheap'], [/hostinger/i, 'hostinger'], [/digitalocean/i, 'digitalocean'], [/kinsta/i, 'kinsta'], [/wp ?engine/i, 'wpengine'],
  [/akamai/i, 'akamai'], [/fastly/i, 'fastly'], [/caddy/i, 'caddy'], [/^express/i, 'express'],
  [/jquery/i, 'jquery'], [/bootstrap/i, 'bootstrap'], [/next\.?js/i, 'nextdotjs'], [/^react/i, 'react'], [/nuxt/i, 'nuxt'], [/^vue/i, 'vuedotjs'], [/angular/i, 'angular'],
  [/gatsby/i, 'gatsby'], [/svelte/i, 'svelte'], [/tailwind/i, 'tailwindcss'],
  [/tag manager/i, 'googletagmanager'], [/analytics/i, 'googleanalytics'], [/^meta\b|facebook/i, 'meta'], [/tiktok/i, 'tiktok'], [/hotjar/i, 'hotjar'],
  [/yoast/i, 'yoast'], [/wp rocket/i, 'wprocket'], [/mailchimp/i, 'mailchimp'], [/instagram/i, 'instagram'], [/whatsapp|click to chat/i, 'whatsapp'], [/^google$|site kit/i, 'google'],
];
// Plain line drawings for things that have no brand: a domain name, the security certificate, and "not detected".
const LINE = {
  globe: '<circle cx="12" cy="12" r="8.5"/><path d="M3.5 12h17M12 3.5c2.6 2.4 3.9 5.2 3.9 8.5s-1.3 6.1-3.9 8.5c-2.6-2.4-3.9-5.2-3.9-8.5S9.4 5.9 12 3.5z"/>',
  lock: '<rect x="5.5" y="10.5" width="13" height="9.5" rx="2.5"/><path d="M8.5 10.5V8a3.5 3.5 0 0 1 7 0v2.5"/>',
  none: '<circle cx="12" cy="12" r="8.5" stroke-dasharray="2.6 3.2"/>',
};
const clean = name => String(name || '').replace(/^DNS:\s*/i, '').trim();
// The brand for a detected name, or null. Returns { slug, hex, path }.
export function techBrand(name) {
  const n = clean(name), hit = RULES.find(([re]) => re.test(n));
  return hit && ICONS[hit[1]] ? { slug: hit[1], hex: ICONS[hit[1]][0], path: ICONS[hit[1]][1] } : null;
}
// A stand-alone SVG file for a brand, used when the icon has to become a picture (the PowerPoint export).
export const techSvg = b => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="96" height="96"><path fill="#${b.hex}" d="${b.path}"/></svg>`;
// The little icon tile shown in front of a tech name. Falls back to a line drawing or the first letter.
export function techIcon(name, group) {
  const n = clean(name), b = group === 'Domain' ? null : techBrand(n); // a domain is a name, not a product, so it never gets a brand logo
  if (b) return `<span class="ti" aria-hidden="true"><svg viewBox="0 0 24 24"><path fill="#${b.hex}" d="${b.path}"/></svg></span>`;
  const line = /^not detected/i.test(n) ? 'none' : /certificate|ssl/i.test(n) ? 'lock' : group === 'Domain' ? 'globe' : '';
  if (line) return `<span class="ti line" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${LINE[line]}</svg></span>`;
  const ch = (n.match(/[A-Za-z0-9]/) || ['?'])[0].toUpperCase();
  return `<span class="ti letter" aria-hidden="true">${ch}</span>`;
}
